/* Маска суши, экваториальная проекция 180x90, 1 бит на ячейку (шаг 2 градуса) */
var LANDMASK="";
var LM_W=180, LM_H=90;
function landPoints(){
  var bin=atob(LANDMASK), pts=[], i=0;
  for(var r=0;r<LM_H;r++)for(var c=0;c<LM_W;c++,i++){
    var b=bin.charCodeAt(i>>3);
    if(b&(128>>(i&7))) pts.push([90-2*(r+0.5), -180+2*(c+0.5)]);
  }
  return pts;
}
